use rusqlite::{params,Connection};
use serde::{Deserialize,Serialize};
use std::{fs, path::PathBuf};

#[derive(Serialize,Deserialize,Clone)] pub struct Knowledge {pub id:String,pub name:String,pub status:String,pub note:String,pub review:Option<String>}
#[derive(Serialize,Deserialize,Clone)] pub struct Branch {pub id:String,pub name:String,pub items:Vec<Knowledge>}
#[derive(Serialize,Deserialize,Clone)] pub struct Direction {pub id:String,pub name:String,pub description:String,pub branches:Vec<Branch>}
fn root()->PathBuf{PathBuf::from(std::env::var_os("GRAYBOX_DATA_ROOT").unwrap_or_else(||"D:\\Graybox".into()))}
fn db()->Result<Connection,String>{fs::create_dir_all(root()).map_err(|_|"无法创建 D 盘 Graybox 数据目录。")?;let c=Connection::open(root().join("graybox.sqlite")).map_err(|_|"无法打开 D 盘 Graybox 数据库。")?;c.execute_batch("PRAGMA foreign_keys=ON; CREATE TABLE IF NOT EXISTS learning_directions(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS learning_branches(id TEXT PRIMARY KEY,direction_id TEXT NOT NULL REFERENCES learning_directions(id) ON DELETE CASCADE,name TEXT NOT NULL,created_at TEXT NOT NULL); CREATE TABLE IF NOT EXISTS learning_knowledge(id TEXT PRIMARY KEY,branch_id TEXT NOT NULL REFERENCES learning_branches(id) ON DELETE CASCADE,name TEXT NOT NULL,status TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',review TEXT,created_at TEXT NOT NULL);").map_err(|_|"无法初始化学习数据库表。")?;Ok(c)}
fn now()->String{format!("{}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_secs())}
#[tauri::command] pub fn learning_list()->Result<Vec<Direction>,String>{let c=db()?;let mut ds=Vec::new();let mut q=c.prepare("SELECT id,name,description FROM learning_directions ORDER BY created_at,id").map_err(|_|"读取学习方向失败。")?;let rows=q.query_map([],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?,r.get::<_,String>(2)?))).map_err(|_|"读取学习方向失败。")?;for row in rows{let (id,name,description)=row.map_err(|_|"读取学习方向失败。")?;let mut branches=Vec::new();let mut bq=c.prepare("SELECT id,name FROM learning_branches WHERE direction_id=? ORDER BY created_at,id").map_err(|_|"读取学习分支失败。")?;let br=bq.query_map([&id],|r|Ok((r.get::<_,String>(0)?,r.get::<_,String>(1)?))).map_err(|_|"读取学习分支失败。")?;for b in br{let (bid,bname)=b.map_err(|_|"读取学习分支失败。")?;let mut items=Vec::new();let mut kq=c.prepare("SELECT id,name,status,note,review FROM learning_knowledge WHERE branch_id=? ORDER BY created_at,id").map_err(|_|"读取知识点失败。")?;let kr=kq.query_map([&bid],|r|Ok(Knowledge{id:r.get(0)?,name:r.get(1)?,status:r.get(2)?,note:r.get(3)?,review:r.get(4)?})).map_err(|_|"读取知识点失败。")?;for item in kr{items.push(item.map_err(|_|"读取知识点失败。")?);}branches.push(Branch{id:bid,name:bname,items});}ds.push(Direction{id,name,description,branches});}Ok(ds)}
#[tauri::command] pub fn learning_create_direction(name:String,description:String)->Result<Direction,String>{let id=uuid::Uuid::new_v4().to_string();let c=db()?;c.execute("INSERT INTO learning_directions(id,name,description,created_at) VALUES(?,?,?,?)",params![id,name.trim(),description.trim(),now()]).map_err(|_|"创建学习方向失败。")?;Ok(Direction{id,name:name.trim().into(),description:description.trim().into(),branches:vec![]})}
#[tauri::command] pub fn learning_create_branch(direction_id:String,name:String)->Result<Branch,String>{let id=uuid::Uuid::new_v4().to_string();let c=db()?;c.execute("INSERT INTO learning_branches(id,direction_id,name,created_at) VALUES(?,?,?,?)",params![id,direction_id,name.trim(),now()]).map_err(|_|"创建学习分支失败。")?;Ok(Branch{id,name:name.trim().into(),items:vec![]})}
#[tauri::command] pub fn learning_create_knowledge(branch_id:String,name:String,status:String,note:String,review:Option<String>)->Result<Knowledge,String>{let id=uuid::Uuid::new_v4().to_string();let c=db()?;c.execute("INSERT INTO learning_knowledge(id,branch_id,name,status,note,review,created_at) VALUES(?,?,?,?,?,?,?)",params![id,branch_id,name.trim(),status,note.trim(),review,now()]).map_err(|_|"创建知识点失败。")?;Ok(Knowledge{id,name:name.trim().into(),status,note:note.trim().into(),review})}
